import { rendererLogger as logger } from "../utils/index.js";
import { getExtensionName } from "../utils/path-utils.js";
import { RENDER_ERROR } from "../errors/index.js";
import { createDefaultMDXComponents } from "./utils/index.js";
import { extractRouteParams } from "../utils/route-path-utils.js";
import { handleComponentPage } from "./component-handling.js";
import { handleMDXPage } from "./page-rendering.js";
import { handleScriptPage } from "./script-page-handling.js";
import { withSpan } from "../observability/tracing/otlp-setup.js";
import { resolveProjectReactVersion } from "../transforms/esm/package-registry.js";
export class PageRenderer {
    projectDir;
    /** Compile vocabulary: "development" | "production". */
    mode;
    /**
     * Request vocabulary: "preview" | "production". Drives studio
     * instrumentation. Only the fallback: a per-render environment wins.
     */
    environment;
    config;
    adapter;
    componentRegistry;
    compileMDX;
    moduleServerUrl;
    isLocalProject;
    constructor(options) {
        this.projectDir = options.projectDir;
        this.mode = options.mode;
        this.environment = options.environment;
        this.config = options.config;
        this.adapter = options.adapter;
        this.componentRegistry = options.componentRegistry;
        this.compileMDX = options.compileMDX;
        this.moduleServerUrl = options.moduleServerUrl;
        this.isLocalProject = options.isLocalProject === true;
    }
    async getMergedComponents(dependencyPinningCacheKey, dependencyPinningDependencies, dependencyPinningSource, moduleServerOrigin, environment = this.environment, dependencyPinningConfiguredVersions, reactPeers) {
        const snapshotKey = await this.componentRegistry.prepareDependencySnapshot(dependencyPinningCacheKey, dependencyPinningDependencies, dependencyPinningSource, moduleServerOrigin, this.config.build?.serverExternalPackages, environment, dependencyPinningConfiguredVersions, reactPeers);
        return {
            ...createDefaultMDXComponents(),
            ...this.componentRegistry.getAllAsComponents(snapshotKey),
        };
    }
    getReactVersion(dependencyPinningCacheKey, dependencyPinningDependencies, dependencyPinningConfiguredVersions, reactPeers) {
        if (dependencyPinningDependencies !== undefined ||
            dependencyPinningCacheKey?.startsWith("on:")) {
            return resolveProjectReactVersion({
                reactPeers,
                adapter: this.adapter,
                projectDir: this.projectDir,
                config: this.config,
                dependencyPinningCacheKey,
                dependencyPinningDependencies,
                dependencyPinningConfiguredVersions,
            });
        }
        return resolveProjectReactVersion({
            reactPeers,
            adapter: this.adapter,
            projectDir: this.projectDir,
            config: this.config,
        });
    }
    detectPageType(pageInfo) {
        const extension = getExtensionName(pageInfo.entity.path);
        if (extension === "tsx" || extension === "jsx") {
            return { type: "component", extension };
        }
        if (extension === "ts" || extension === "js") {
            return { type: "script", extension };
        }
        return { type: "mdx", extension };
    }
    preparePageBundles(pageInfo, slug, cachedModule, options) {
        const pageType = this.detectPageType(pageInfo);
        return withSpan("render.prepare_page", async () => {
            logger.debug(`Page file info:`, {
                path: pageInfo.entity.path,
                extension: pageType.extension,
                type: pageType.type,
                slug,
            });
            if (pageType.type === "script") {
                const scriptResult = await withSpan("render.handle_script", () => handleScriptPage(pageInfo, slug, {
                    mode: this.mode,
                    reactPeers: options?.reactPeers,
                    config: this.config,
                    projectDir: this.projectDir,
                    adapter: this.adapter,
                    params: options?.params,
                    url: options?.url,
                    props: options?.props,
                    nonce: options?.nonce,
                    releaseId: options?.releaseId,
                    dependencyPinningCacheKey: options?.dependencyPinningCacheKey,
                    dependencyPinningDependencies: options?.dependencyPinningDependencies,
                    dependencyPinningConfiguredVersions: options?.dependencyPinningConfiguredVersions,
                }), { "render.script_path": pageInfo.entity.path });
                return { collectedMetadata: {}, scriptResult };
            }
            const reactVersion = await this.getReactVersion(options?.dependencyPinningCacheKey, options?.dependencyPinningDependencies, options?.dependencyPinningConfiguredVersions, options?.reactPeers);
            if (pageType.type === "component") {
                let params = options?.params;
                if (!params || Object.keys(params).length === 0) {
                    const extracted = extractRouteParams(pageInfo.entity.path, slug, this.config.directories);
                    params = extracted.matched ? extracted.params : undefined;
                }
                const componentProps = {
                    ...options?.props,
                    ...(params && Object.keys(params).length > 0 ? { params } : {}),
                };
                const result = await withSpan("render.handle_component", () => handleComponentPage(pageInfo, slug, this.projectDir, this.componentRegistry, this.adapter, {
                    props: componentProps,
                    cachedClientModule: cachedModule?.type === "component"
                        ? cachedModule.code
                        : undefined,
                    moduleServerUrl: this.moduleServerUrl,
                    moduleServerOrigin: options?.url?.origin,
                    projectId: options?.projectId,
                    studioEmbed: options?.studioEmbed,
                    mode: this.mode,
                    environment: options?.environment ?? this.environment,
                    contentSourceId: options?.contentSourceId,
                    reactVersion,
                    reactPeers: options?.reactPeers,
                    dependencyPinningCacheKey: options?.dependencyPinningCacheKey,
                    dependencyPinningDependencies: options?.dependencyPinningDependencies,
                    dependencyPinningConfiguredVersions: options?.dependencyPinningConfiguredVersions,
                    dependencyPinningSource: options?.dependencyPinningSource,
                    serverExternalPackages: this.config.build?.serverExternalPackages,
                    signal: options?.abortSignal,
                }), { "render.component_path": pageInfo.entity.path });
                return {
                    pageElement: result.pageElement,
                    pageBundle: result.pageBundle,
                    clientModuleCode: result.pageBundle.clientModuleCode ?? cachedModule?.code,
                    pageModuleType: "component",
                    collectedMetadata: {},
                };
            }
            const mdxResult = await withSpan("render.handle_mdx", async () => handleMDXPage(pageInfo, slug, this.projectDir, await this.getMergedComponents(options?.dependencyPinningCacheKey, options?.dependencyPinningDependencies, options?.dependencyPinningSource, options?.url?.origin, options?.environment ?? this.environment, options?.dependencyPinningConfiguredVersions, options?.reactPeers), this.compileMDX, this.adapter, {
                params: options?.params,
                url: options?.url,
                precompiledModule: cachedModule?.type === "mdx" ? cachedModule.code : undefined,
                projectId: options?.projectId,
                studioEmbed: options?.studioEmbed,
                projectSlug: options?.projectSlug,
                mode: this.mode,
                contentSourceId: options?.contentSourceId,
                reactVersion,
                reactPeers: options?.reactPeers,
                serverExternalPackages: this.config.build?.serverExternalPackages,
                dependencyPinningCacheKey: options?.dependencyPinningCacheKey,
                dependencyPinningDependencies: options?.dependencyPinningDependencies,
                dependencyPinningConfiguredVersions: options?.dependencyPinningConfiguredVersions,
                dependencyPinningSource: options?.dependencyPinningSource,
                isLocalProject: this.isLocalProject,
            }), { "render.mdx_path": pageInfo.entity.path });
            return {
                pageElement: mdxResult.pageElement,
                pageBundle: mdxResult.pageBundle,
                clientModuleCode: mdxResult.pageBundle.clientModuleCode,
                pageModuleType: "mdx",
                collectedMetadata: mdxResult.collectedMetadata,
            };
        }, {
            "render.page_type": pageType.type,
            "render.slug": slug,
            "render.path": pageInfo.entity.path,
            "render.has_cached_module": !!cachedModule,
        });
    }
    getPageType(pageInfo) {
        const detected = this.detectPageType(pageInfo);
        const descriptions = {
            mdx: "MDX content page with React components",
            component: "React component page (TSX/JSX)",
            script: "Script page returning Response (TS/JS)",
        };
        return { ...detected, description: descriptions[detected.type] };
    }
    validatePageBundle(result, slug) {
        if (result.scriptResult)
            return;
        if (result.pageElement && result.pageBundle)
            return;
        throw RENDER_ERROR.create({
            detail: "Failed to prepare page bundle",
            context: {
                slug,
                hasElement: !!result.pageElement,
                hasBundle: !!result.pageBundle,
            },
        });
    }
}
